func TestVO2maxNorm(t *testing.T) {
	cases := []struct {
		p    Profile
		v    float64
		want string
		tone string
	}{
		{Profile{Age: 45}, 47, "für Männer 40–49: ausgezeichnet (hervorragend ab 52,5)", ToneGood},
		{Profile{Age: 45}, 53, "für Männer 40–49: hervorragend", ToneGood},
		{Profile{Age: 45}, 38, "für Männer 40–49: gering (ausreichend ab 38,5)", ToneBad},
		{Profile{Age: 33, Female: true}, 40, "für Frauen 30–39: gut (ausgezeichnet ab 42,4)", ToneNeutral},
		{Profile{Age: 85}, 43, "für Männer 70–79: hervorragend", ToneGood},
		{Profile{Age: 16}, 46, "für Männer 20–29: gut (ausgezeichnet ab 51,1)", ToneNeutral},
	}
	for _, c := range cases {
		got, ok := VO2maxNorm(c.p, c.v)
		if !ok || got.Text != c.want || got.Tone != c.tone {
			t.Errorf("VO2maxNorm(%+v, %v) = %+v, want %q/%s", c.p, c.v, got, c.want, c.tone)
		}
	}
	if _, ok := VO2maxNorm(Profile{}, 50); ok {
		t.Error("unknown profile must not be rated")
	}
}

func TestSimpleNorms(t *testing.T) {
	if s := RestingHRNorm(52); s.Tone != ToneGood || !strings.Contains(s.Text, "Trainierte") {
		t.Errorf("RHR 52: %+v", s)
	}
	if s := RestingHRNorm(105); s.Tone != ToneBad {
		t.Errorf("RHR 105: %+v", s)
	}
	if s := SleepNorm(Profile{Age: 45}, 6.5*3600); s.Tone != ToneBad || s.Text != "⌀ 30 Tage 6:30 h – unter der Empfehlung (empfohlen 7–9 h)" {
		t.Errorf("sleep: %+v", s)
	}
	if s := SleepNorm(Profile{Age: 70}, 8.5*3600); s.Tone != ToneNeutral || !strings.Contains(s.Text, "7–8 h") {
		t.Errorf("sleep 70: %+v", s)
	}
	if s := StepsNorm(Profile{Age: 45}, 7310); s.Tone != ToneGood || s.Text != "⌀ 30 Tage 7.310 – Orientierung 7.000–10.000" {
		t.Errorf("steps: %+v", s)
	}
	if s := StepsNorm(Profile{Age: 62}, 5500); s.Tone != ToneBad || !strings.Contains(s.Text, "6.000–8.000") {
		t.Errorf("steps 62: %+v", s)
	}
}

func TestReview(t *testing.T) {
	base := Baseline([]PeriodFigures{
		{Activities: 3, DistanceM: 100000, Load: 400, Sleep: 7 * 3600, RestingHR: 50, HRV: 60},
		{Activities: 4, DistanceM: 120000, Load: 600, Sleep: 7 * 3600, RestingHR: 52, HRV: 60},
		{}, // empty week: counts for sums, not for health
		{Activities: 3, DistanceM: 80000, Load: 200, Sleep: 7 * 3600, RestingHR: 50, HRV: 60},
	})
	if base.Load != 300 || base.DistanceM != 75000 || base.RestingHR != 152.0/3 || base.Sleep != 7*3600 {
		t.Fatalf("baseline = %+v", base)
	}
	cur := PeriodFigures{Load: 360, DistanceM: 78000, Sleep: 7*3600 - 25*60, RestingHR: 54, HRV: 61,
		Records: []string{"10 km Laufen", "5 min Leistung"}}
	got := Review(cur, base, 1, "4-Wochen-Schnitt")
	want := []string{
		"Belastung 20 % über deinem 4-Wochen-Schnitt",
		"Schlaf 25 min unter deinem Üblichen",
		"Ruhepuls 3 bpm über deinem Üblichen",
		"2 neue Bestleistungen (10 km Laufen, 5 min Leistung)",
	}
	if len(got) != len(want) {
		t.Fatalf("Review = %+v", got)
	}
	for i := range want {
		if got[i].Text != want[i] {
			t.Errorf("statement %d = %q, want %q", i, got[i].Text, want[i])
		}
	}
	if got[1].Tone != ToneBad || got[3].Tone != ToneGood {
		t.Errorf("tones: %+v", got)
	}

	// A running week is compared pro rata; too early, sums are skipped.
	running := Review(PeriodFigures{Load: 150, DistanceM: 32000}, base, 3.0/7, "4-Wochen-Schnitt")
	if len(running) != 1 || running[0].Text != "Belastung 17 % über deinem 4-Wochen-Schnitt" {
		t.Errorf("running = %+v", running)
	}
	if early := Review(PeriodFigures{Load: 0}, base, 1.0/7, "x"); len(early) != 0 {
		t.Errorf("early = %+v", early)
	}
}

func TestReviewCapsAtFour(t *testing.T) {
	base := PeriodFigures{Load: 100, DistanceM: 100, Sleep: 8 * 3600, RestingHR: 50, HRV: 60}
	cur := PeriodFigures{Load: 200, DistanceM: 200, Sleep: 7 * 3600, RestingHR: 55, HRV: 40, Records: []string{"a", "b", "c", "d"}}
	got := Review(cur, base, 1, "x")
	if len(got) != 4 || got[3].Text != "4 neue Bestleistungen (a, b, c, …)" {
		t.Errorf("Review = %+v", got)
	}
}

func TestAssessTrend(t *testing.T) {
	nan := math.NaN()
	bpm := func(v float64) string { return comma("%.0f bpm", v) }
	tr, ok := AssessTrend(TrendMetric{Label: "Ruhepuls", Current: 49, Previous: 52, LastYear: 50, Threshold: 2,
		LowerBetter: true, Unit: "bpm", Format: bpm})
	if !ok || tr.Stable || tr.Statement.Text != "Ruhepuls 49 bpm: 3 bpm niedriger als die 90 Tage davor" || tr.Statement.Tone != ToneGood {
		t.Errorf("rhr = %+v", tr)
	}
	tr, _ = AssessTrend(TrendMetric{Label: "Schnellste 40 km", Current: 4000, Previous: nan, LastYear: 4200, Threshold: 0.03,
		Relative: true, Time: true, LowerBetter: true, Format: func(v float64) string { return "t" }})
	if tr.Statement.Text != "Schnellste 40 km t: 5 % schneller als vor einem Jahr" || tr.Statement.Tone != ToneGood {
		t.Errorf("time = %+v", tr)
	}
	tr, _ = AssessTrend(TrendMetric{Label: "HRV", Current: 60, Previous: 62, LastYear: 58, Threshold: 0.05, Relative: true, Format: bpm})
	if !tr.Stable {
		t.Errorf("hrv should be stable: %+v", tr)
	}
	if _, ok := AssessTrend(TrendMetric{Label: "x", Current: 1, Previous: nan, LastYear: nan, Format: bpm}); ok {
		t.Error("no reference must give no trend")
	}
	if got := StableLabels([]Trend{{Label: "A", Stable: true}, {Label: "B"}, {Label: "C", Stable: true}}); got != "A, C" {
		t.Errorf("StableLabels = %q", got)
	}
}
